class DonguHatasi(ValueError):
    def __init__(self, dongu):
        self.dongu = dongu
        super().__init__("Döngü tespit edildi: " + " -> ".join(dongu))


def kurulum_sirasi(deps: dict[str, list[str]]) -> list[str]:
    # Grafiği oluştur
    graph = {pkg: [] for pkg in deps}
    for pkg, dependents in deps.items():
        for dep in dependents:
            if dep not in graph:
                graph[dep] = []
            graph[pkg].append(dep)

    # Düğümleri ziyaret etmek için durumlar
    ziyaret_edildi = set()
    islemde = set()
    sirali = []

    def dfs(pkg):
        if pkg in islemde:
            # Döngü tespiti: o düğüm zaten işlemdeyse döngü var
            cycle = []
            for p in reversed(sirali):
                cycle.append(p)
                if p == pkg:
                    break
            raise DonguHatasi(cycle)

        if pkg in ziyaret_edildi:
            return

        islemde.add(pkg)
        # Bağımlılıkları öncelikle ziyaret et
        for dep in graph[pkg]:
            dfs(dep)

        islemde.discard(pkg)
        ziyaret_edildi.add(pkg)
        sirali.append(pkg)

    # Her düğümü DFS ile ziyaret et
    for pkg in sorted(graph.keys()):
        if pkg not in ziyaret_edildi:
            dfs(pkg)

    return sirali

